import type { WalkSnapshot } from '@shared/walks'
import type { AttractionReport, GuideLanguage } from '@shared/types'

/**
 * Bindings come from wrangler.jsonc (and are regenerated by `wrangler types`).
 * Only the secrets and optional local overrides live here.
 */
export type AppEnv = Env & {
  GEMINI_API_KEY?: string
  /** Optional Cloudflare AI Gateway base, e.g. .../google-ai-studio/v1beta/models */
  AI_GATEWAY_URL?: string
  BETTER_AUTH_SECRET?: string
  GOOGLE_CLIENT_ID?: string
  GOOGLE_CLIENT_SECRET?: string
  MIGRATE_SECRET?: string
  /** Per-user daily limits. Both default in worker/routes/analyses.ts. */
  DAILY_ANALYSES?: string
  DAILY_CHATS?: string
  /** Pi's model. Defaults to the Workers AI narrator in worker/walk/agent.ts. */
  WALK_MODEL?: string
  /**
   * The walk Durable Object. Declared explicitly so the API still typechecks
   * before `wrangler types` has been regenerated.
   */
  WALK_AGENT?: DurableObjectNamespace
}

/**
 * The RPC surface of `WalkAgent`, as the Worker sees it.
 *
 * Durable Object stubs are untyped by default; this is the one place the
 * caller asserts the shape instead of leaking `any` through the routes.
 */
export interface WalkAgentRpc {
  start(input: {
    walkId: string
    planId: string
    language: GuideLanguage
  }): Promise<WalkSnapshot>
  snapshot(): Promise<WalkSnapshot>
  message(input: {
    text?: string
    photoKey?: string
    mimeType?: string
    /** Survives a client retry: the same id is one submission. */
    operationId?: string
  }): Promise<{ answer: string; snapshot: WalkSnapshot }>
  advance(input?: { note?: string }): Promise<{ answer: string; snapshot: WalkSnapshot }>
  reset(): Promise<WalkSnapshot>
}

/**
 * The frame the traveller was sent to take, when the guide is asking for a
 * second shot. It is what turns one analysis into a walk.
 */
export interface VisionContinuation {
  placeTitle: string
  placeName: string
  /** The shot the traveller was asked to take, in their words. */
  instruction: string
}

/** A nearby Wikipedia article, used only as a hypothesis for the model. */
export interface NearbyPlace {
  title: string
  /** Distance from the traveller in metres, when the source reports it. */
  distance?: number
}

export interface VisionInput {
  image: ArrayBuffer
  mimeType: string
  location?: { latitude: number; longitude: number; accuracy?: number }
  /** Compass heading in degrees, when the device reports one. */
  heading?: number
  /** Nearby article titles. The model must still confirm them visually. */
  nearby?: NearbyPlace[]
  /** A place name the traveller picked after a low-confidence answer. */
  hint?: string
  language: GuideLanguage
  continuation?: VisionContinuation
}

export interface ChatImage {
  data: ArrayBuffer
  mimeType: string
}

export interface VisionProvider {
  readonly name: 'gemini' | 'mock'
  readonly model?: string
  analyze(input: VisionInput): Promise<AttractionReport>
  chat(input: {
    report: AttractionReport
    history: { role: 'user' | 'assistant'; content: string }[]
    question: string
    language: GuideLanguage
    /** The archived photograph. Chat is photo-aware, not report-only. */
    image?: ChatImage
  }): Promise<string>
}

export class ProviderError extends Error {
  code: string
  status: number

  constructor(message: string, code = 'provider_error', status = 502) {
    super(message)
    this.name = 'ProviderError'
    this.code = code
    this.status = status
  }
}
